select o.*,t.tearoom_name as tearoomName,t.tearoom_title_image as tearoomTitleImage, u1.user_name as zhiUserName,u2.user_name as feiUserName,u.user_name as payUserName, u.avatar as payAvatar,u.phone as payPhone,g.icon_img as iconImg, openUser.user_name as openUserName,closeUser.user_name as closeUserName from orders o left join tearoom t on t.tearoom_id=o.tearoom_id left join goods g on g.goods_id=o.goods_id left join tb_user u on u.user_id=o.user_id left join tb_user u1 on u1.user_id=o.zhi_user_id left join tb_user u2 on u2.user_id=o.fei_user_id left join tb_user openUser on openUser.user_id=o.open_user_id left join tb_user closeUser on closeUser.user_id=o.close_user_id where 1=1
and o.orders_type = #{ordersType}
and o.open_user_id = #{openUserId}
and o.goods_category in (1,2,3)
and o.goods_category = #{goodsCategory}
and o.is_delete is null
and o.pay_way=#{payWay}
and o.sum_money<0
and o.sum_money>=0
and o.user_id=#{userId}
and u.user_name like concat('%',#{userName},'%')
and u.phone like concat('%',#{phone},'%')
and o.orders_no like concat('%',#{ordersNo},'%')
and o.goods_name like concat('%',#{goodsName},'%')
and o.status=#{status}
and o.status in (2,3,4,6)
and o.status in (4,6) and o.shop_money>0
and o.tearoom_id=#{tearoomId}
and o.is_shop=#{isShop}
and o.is_shop is null
and date_format(o.create_time,'%Y-%m-%d')>=date_format(#{startTime},'%Y-%m-%d')
and date_format(o.create_time,'%Y-%m-%d')<=date_format(#{endTime},'%Y-%m-%d')
and o.create_time like concat('%',#{dateTime},'%')
and o.goods_id in (select goods_id from goods where camera_id=#{cameraId})
and t.tearoom_name like concat('%',#{tearoomName},'%')
and o.platform_type = #{platformType}
order by o.create_time desc

select o.*,t.tearoom_name as tearoomName,u1.user_name as zhiUserName,u2.user_name as feiUserName,u.user_name as payUserName
from orders o
left join tearoom t on t.tearoom_id=o.tearoom_id
left join tb_user u on u.user_id=o.user_id
left join tb_user u1 on u1.user_id=o.zhi_user_id
left join tb_user u2 on u2.user_id=o.fei_user_id
where 1=1

    and o.orders_type = #{ordersType}


    and o.open_user_id = #{openUserId}


    and o.goods_category in (1,2,3)


    and o.goods_category = #{goodsCategory}


    and o.is_delete is null


    and o.sum_money<0


    and o.sum_money>=0


    and o.pay_way=#{payWay}


    and o.user_id=#{userId}


    and u.user_name like concat('%',#{userName},'%')


    and u.phone like concat('%',#{phone},'%')


    and o.orders_no like concat('%',#{ordersNo},'%')


    and o.goods_name like concat('%',#{goodsName},'%')


    and o.status=#{status}


    and o.tearoom_id=#{tearoomId}


    and o.is_shop=#{tearoomId}


    and o.is_shop is null


    and date_format(o.start_time,'%Y-%m-%d')>=date_format(#{startTime},'%Y-%m-%d')


    and date_format(o.end_time,'%Y-%m-%d')<=date_format(#{endTime},'%Y-%m-%d')


    and o.create_time like concat('%',#{dateTime},'%')


    and t.tearoom_name like concat('%',#{tearoomName},'%')


    and o.platform_type = #{platformType}

order by o.create_time desc

