and date_format(o.create_time,'%Y-%m-%d')>=date_format(#{time},'%Y-%m-%d') and date_format(o.create_time,'%Y-%m-%d')<=date_format(#{endTime},'%Y-%m-%d')

select count(*) from orders o where o.status=4 and o.tearoom_id=#{tearoomId}
and pay_way=#{payWay}
and date_format(o.create_time,'%Y-%m-%d')=date_format(#{time},'%Y-%m-%d')
and date_format(o.create_time,'%Y-%m')=date_format(#{time},'%Y-%m')
and date_format(o.create_time,'%Y')=date_format(#{time},'%Y')
and date_format(o.create_time,'%Y-%m-%d')>=date_format(#{time},'%Y-%m-%d') and date_format(o.create_time,'%Y-%m-%d')<=date_format(#{endTime},'%Y-%m-%d')

SELECT user_id as userId, user_name as userName, avatar, sex, (select um.money from user_money um where um.user_id=subquery.user_id) as userMoney, ifnull(MAX( order_duration ),0) AS duration, count(*) as ordersCount, (select vip_icon from vip v where v.vip_index=vipIndex) as vipIcon FROM ( -- 子查询用于计算每个人的订单时长 SELECT u.user_id,u.user_name,u.avatar,u.sex,u.vip_index as vipIndex, sum(TIMESTAMPDIFF( MINUTE, STR_TO_DATE( o.pay_time, '%Y-%m-%d %H:%i:%s' ), STR_TO_DATE( o.end_time, '%Y-%m-%d %H:%i:%s' ))) AS order_duration FROM orders o LEFT JOIN tb_user u ON u.user_id=o.user_id where o.status in (4,6) and u.user_id=#{userId}
and date_format(o.pay_time,'%Y-%m')=date_format(now(),'%Y-%m')
-- 将 startTime 从 varchar 转换为日期类型，并筛选出上个月的记录 and STR_TO_DATE(o.pay_time, '%Y-%m-%d %H:%i:%s') BETWEEN -- 获取上个月的第一天 DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 MONTH), '%Y-%m-01') AND -- 获取上个月的最后一天 LAST_DAY(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))
-- 将 starTime 从 varchar 转换为日期时间类型，并筛选本周的记录 and STR_TO_DATE(o.pay_time, '%Y-%m-%d %H:%i:%s') BETWEEN -- 获取本周的第一天（周一） DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE()) DAY) AND -- 获取本周的最后一天（周日） DATE_ADD(DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE()) DAY), INTERVAL 6 DAY)
-- 将 starTime 从 varchar 转换为日期时间类型，并筛选上周的记录 and STR_TO_DATE(o.pay_time, '%Y-%m-%d %H:%i:%s') BETWEEN -- 获取上周的第一天（周一） DATE_SUB(DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE()) DAY), INTERVAL 1 WEEK) AND -- 获取上周的最后一天（周日） DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE()) DAY), INTERVAL 6 DAY), INTERVAL 1 WEEK)
and o.tearoom_id in (select tearoom_id from tearoom where tearoom_city like concat('%',#{city},'%'))
and o.tearoom_id = #{tearoomId}
) AS subquery GROUP BY user_id order by duration desc

select IFNULL(SUM(IF(shop_pay_money IS NULL, pay_money, shop_pay_money)), 0.00) from orders where tearoom_id=#{tearoomId} and status in (4,6)
