select IFNULL(SUM(IF(shop_pay_money IS NULL, pay_money, shop_pay_money)), 0.00) as sumMoney from orders where user_id is not null and is_shop is null and status in (3,4,6,7,8) and tearoom_id=#{tearoomId} and pay_way=#{payWay}
